  function formatDateRu2(dateStr) {
    if (!dateStr) return "";
    const parts = dateStr.split("-");
    if (parts.length === 3) {
      const day = parseInt(parts[2], 10);
      const months = [
        "января",
        "февраля",
        "марта",
        "апреля",
        "мая",
        "июня",
        "июля",
        "августа",
        "сентября",
        "октября",
        "ноября",
        "декабря"
      ];
      const month = months[parseInt(parts[1], 10) - 1] || "";
      return `${day} ${month} ${parts[0]} г.`;
    }
    return dateStr;
  }
