  // .build/task-07-analytics-attendance/4/src/views/analytics/listeners.js
  function setupAnalyticsListeners(onNavigate) {
    const periodSelect = document.getElementById("select-analytics-period");
    const btnGenerateReport = document.getElementById("btn-generate-report");
    const reportContainer = document.getElementById("report-container");
    const btnCloseReport = document.getElementById("btn-close-report");
    const btnPrintReport = document.getElementById("btn-print-report");
    if (periodSelect) {
      periodSelect.addEventListener("change", () => {
        const selectedPeriod = periodSelect.value;
        const isReportOpen = reportContainer && !reportContainer.classList.contains("hidden");
        if (onNavigate) {
          onNavigate(
            `/analytics?periodId=${selectedPeriod}${isReportOpen ? "&showReport=true" : ""}`
          );
        }
      });
    }
    if (btnGenerateReport && reportContainer) {
      btnGenerateReport.addEventListener("click", () => {
        reportContainer.classList.remove("hidden");
        reportContainer.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    }
    if (btnCloseReport && reportContainer) {
      btnCloseReport.addEventListener("click", () => {
        reportContainer.classList.add("hidden");
      });
    }
    if (btnPrintReport) {
      btnPrintReport.addEventListener("click", () => {
        window.print();
      });
    }
  }

  // .build/task-07-analytics-attendance/4/src/views/accounts/helpers.js
  var PAGE_SIZE = 10;
  var ROLE_OPTIONS = [
    "admin",
    "teacher",
    "subject_teacher",
    "parent",
    "student"
  ];
  var ACCOUNT_ROLE_LABELS = {
    ...ROLE_LABELS,
    subject_teacher: "Учитель"
  };
  var ROLE_BADGE_CLASSES = {
    admin: "bg-rose-100 text-rose-700",
    teacher: "bg-violet-100 text-violet-700",
    subject_teacher: "bg-sky-100 text-sky-700",
    parent: "bg-emerald-100 text-emerald-700",
    student: "bg-slate-200 text-slate-700"
  };
  function getBindingLabel(user, db) {
    switch (user.role) {
      case "teacher":
        return user.cardName ? `Учитель: ${user.cardName}` : user.className || "Классный руководитель";
      case "subject_teacher":
        return user.cardName ? `Учитель: ${user.cardName}` : user.subject || "Без нагрузки";
      case "parent":
        return user.childName || "Без привязки";
      case "student": {
        const student = (db.students || []).find((s) => s.id === user.studentId);
        if (student) {
          return `Ученик: ${student.shortName || student.fullName}`;
        }
        return user.className || "Без привязки";
      }
      case "admin":
        return "Все классы школы";
      default:
        return "—";
    }
  }
  function getCardOptions(db, role, user = null) {
    if (role === "student" || role === "parent") {
      return (db.students || []).map((s) => ({ id: s.id, label: s.fullName }));
    }
    if (role === "teacher" || role === "subject_teacher") {
      const names = [...new Set((db.subjects || []).map((s) => s.teacher))];
      if (user && user.shortName && !names.includes(user.shortName)) {
        names.push(user.shortName);
      }
      return names.map((name) => ({ id: name, label: name }));
    }
    return [];
  }
  function formatLastLogin(isoValue, demoToday) {
    if (!isoValue) return "—";
    const dateStr = isoValue.slice(0, 10);
    const timeStr = isoValue.slice(11, 16);
    if (dateStr === demoToday) {
      return timeStr ? `Сегодня, ${timeStr}` : "Сегодня";
    }
    const demoDate = /* @__PURE__ */ new Date(`${demoToday}T00:00:00`);
    const prevDate = /* @__PURE__ */ new Date(`${dateStr}T00:00:00`);
    const diffDays = Math.round((demoDate - prevDate) / 864e5);
    if (diffDays === 1) {
      return timeStr ? `Вчера, ${timeStr}` : "Вчера";
    }
    const [y, m, d] = dateStr.split("-");
    return `${d}.${m}.${y}${timeStr ? `, ${timeStr}` : ""}`;
  }
  function escapeHtml2(text) {
    return String(text ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
  }
  function statusBadgeHtml(isActive) {
    return isActive ? `<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-100 text-emerald-700">Активен</span>` : `<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-rose-100 text-rose-700">Заблокирован</span>`;
  }
  function roleBadgeHtml(user) {
    const label = ACCOUNT_ROLE_LABELS[user.role] || user.roleLabel || user.role;
    return `<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-semibold ${ROLE_BADGE_CLASSES[user.role] || "bg-slate-100 text-slate-600"}">${escapeHtml2(label)}</span>`;
  }
  function toggleStatusButtonHtml(user, isSelf) {
    const isActive = user.status === "active";
    if (isActive) {
      return `<button type="button" data-action="toggle-status" data-user-id="${user.id}" data-next-status="blocked"
              ${isSelf ? 'disabled title="Нельзя заблокировать собственную учётную запись"' : 'title="Заблокировать учётную запись"'}
              class="px-3 py-1.5 rounded-lg text-[11px] font-semibold border transition-colors ${isSelf ? "border-slate-200 text-slate-300 cursor-not-allowed" : "border-rose-200 text-rose-600 bg-rose-50 hover:bg-rose-100 cursor-pointer"}">Блок</button>`;
    }
    return `<button type="button" data-action="toggle-status" data-user-id="${user.id}" data-next-status="active" title="Разблокировать учётную запись"
            class="px-3 py-1.5 rounded-lg text-[11px] font-semibold border border-emerald-200 text-emerald-700 bg-emerald-50 hover:bg-emerald-100 cursor-pointer">Разблок</button>`;
  }

