  // .build/task-07-analytics-attendance/4/src/views/change-password/listeners.js
  function setupChangePasswordListeners(onNavigate) {
    const currentUser = getCurrentUser();
    if (!currentUser) return;
    const form = document.getElementById("change-password-form");
    const errorBox = document.getElementById("cp-error-box");
    function showError(msg) {
      if (errorBox) {
        errorBox.textContent = msg;
        errorBox.classList.remove("hidden");
      }
    }
    if (form) {
      form.addEventListener("submit", (e) => {
        e.preventDefault();
        const current = (document.getElementById("cp-current") || {}).value || "";
        const next = (document.getElementById("cp-new") || {}).value || "";
        const confirm2 = (document.getElementById("cp-confirm") || {}).value || "";
        const res = changePassword(currentUser.id, current, next, confirm2, true);
        if (!res.success) {
          showError(res.error);
          return;
        }
        const defRoute = getDefaultRouteForRole(currentUser.role);
        navigate(defRoute);
      });
    }
    const logoutBtn = document.getElementById("btn-cp-logout");
    if (logoutBtn) {
      logoutBtn.addEventListener("click", () => {
        logout();
        navigate("/login");
      });
    }
  }

  // .build/task-07-analytics-attendance/4/src/views/teachers/helpers.js
  function escapeHtml3(text) {
    return String(text ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
  }
  function getInitials2(fullName) {
    const parts = String(fullName || "").trim().split(/\s+/);
    if (parts.length < 2) return (fullName || "УЧ").slice(0, 2).toUpperCase();
    return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
  }
  function getTeacherCards(db = getDB()) {
    const users = db.users || [];
    const teachers = db.teachers || [];
    return teachers.map((teacher) => {
      const account = teacher.accountUserId ? users.find((u) => u.id === teacher.accountUserId) : users.find((u) => (u.cardName || u.shortName) === teacher.shortName);
      const workload = (teacher.workload || []).map((w) => {
        const subject = (db.subjects || []).find((s) => s.id === w.subjectId);
        const schoolClass = (db.classes || []).find((c) => c.id === w.classId);
        return {
          className: schoolClass ? schoolClass.name : w.className,
          subjectLabel: subject ? subject.shortName || subject.name : w.subjectLabel,
          hours: w.hours
        };
      });
      const totalHours = workload.reduce((sum, w) => sum + (w.hours || 0), 0);
      const classNames = [...new Set(workload.map((w) => w.className))];
      return {
        teacher,
        account: account || null,
        accountLogin: account ? account.username : null,
        accountStatus: account ? account.status : null,
        workload,
        totalHours,
        classNames,
        subjectLabels: [
          ...new Set(
            (teacher.subjectIds || []).map((id) => {
              const subject = (db.subjects || []).find((s) => s.id === id);
              return subject ? subject.shortName : id;
            })
          )
        ]
      };
    });
  }

